SELECT (coalesce((SELECT md5(prosrc)='fbca4bbb02099956d2138eefe7cd4792' FROM pg_proc WHERE oid=to_regprocedure('public.link_course_outline_content(uuid,uuid,uuid,bigint,uuid,bigint,boolean)')),false) AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261101030000' AND cardinality(statements)=1 AND md5(statements[1])='f169bd75041c4b3accf0d0c437b83d4b') AND EXISTS(SELECT 1 FROM public.courses WHERE id='93124428-92f4-48d2-a6dc-e5f9e010248b' AND practice_course_scope IN ('AB','BC')) AND EXISTS(SELECT 1 FROM public.courses WHERE id='fccc7540-0c29-43be-8682-ae90ff2534cb' AND practice_course_scope='BC')) AS prerequisite_matches,(NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261102000000')) AS repair_absent;
SELECT jsonb_build_object('courses',(SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'scope',practice_course_scope,'revision',outline_revision) ORDER BY id) FROM public.courses),'lessons',(SELECT count(*) FROM public.course_lessons),'videos',(SELECT count(*) FROM public.course_videos),'entries',(SELECT count(*) FROM public.course_outline_entries),'archived',(SELECT count(*) FROM public.course_outline_entries WHERE archived),'content_fingerprint',(SELECT md5(jsonb_build_object('lessons',(SELECT jsonb_agg(to_jsonb(l) ORDER BY id) FROM public.course_lessons l),'videos',(SELECT jsonb_agg(to_jsonb(v) ORDER BY id) FROM public.course_videos v),'bindings',(SELECT jsonb_agg(to_jsonb(b) ORDER BY course_id,topic_id) FROM public.course_lesson_courses b))::text))) AS inventory;
